#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzTexture(int tex,float2 uv) { return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_SPEED;
uniform float amzp_UV_SCALE;
uniform float amzp_STEPS;
uniform float amzp_DENOM_BIAS;
uniform float amzp_GAIN;
uniform float amzp_WOBBLE_FREQ;
uniform float amzp_WOBBLE_AMP;
uniform float amzp_PULL_MIN;
uniform float amzp_PULL_ADD;
uniform float amzp_DOT_MIN;
uniform float amzp_DOT_ADD;
uniform float amzp_PAT_MIN;
uniform float amzp_PAT_ADD;
uniform float amzp_PAT_BASE;
uniform float amzp_PAT_GAIN;
uniform float amzp_THRESH_1;
uniform float amzp_THRESH_2;
uniform float amzp_BRIGHT_1;
uniform float amzp_BRIGHT_2;
uniform float amzp_SHADOW_DECAY;
uniform float amzp_SHADOW_GAIN;
uniform float amzp_R_MIN;
uniform float amzp_R_ADD;
uniform float amzp_G_MIN;
uniform float amzp_G_ADD;
uniform float amzp_B_MIN;
uniform float amzp_B_ADD;
uniform float amzp_GAMMA;



float rand21(float2 c){ return fract(sin(dot(c, float2(12.9898,78.233))) * 43758.5453); }

void amzRender(){
    float2 R = screen.zw;
    float2 frag = amzScreenNorm() * R;
    float2 p = (2.0 * frag - R) / min(R.x, R.y) * amzp_UV_SCALE;

    float z0 = time * amzp_SPEED;
    float i = floor(z0);
    float offs = fract(z0);
    float shadow = 1.0;

    float3 outc = float3(0.0);

    int maxSteps = int(clamp(amzp_STEPS, 1.0, 300.0));
    const int MAX_IT = 300;
    for (int zi = 1; zi < MAX_IT; zi++){
        if (zi >= maxSteps) break;
        float z = float(zi);
        float z2 = z - offs;
        float randz = z + i;

        float dadt = (rand21(float2(randz, 1.0)) * 2.0 - 1.0) * 0.5;
        float a = rand21(float2(randz, 1.0)) * 2.0 * 3.14159265 + dadt * time;
        float pullback = rand21(float2(randz, 3.0)) * amzp_PULL_ADD + amzp_PULL_MIN;
        float r = rand21(float2(randz, 4.0)) * amzp_R_ADD + amzp_R_MIN;
        float g = rand21(float2(randz, 5.0)) * amzp_G_ADD + amzp_G_MIN;
        float b = rand21(float2(randz, 6.0)) * amzp_B_ADD + amzp_B_MIN;

        float2 origin = float2(sin(randz*0.005)+sin(randz*0.002), cos(randz*0.005)+cos(randz*0.002)) * z2 * 0.002;
        float2 dir = float2(cos(a), sin(a));
        float dist = dot(dir, p - origin) * z2;
        float xdist = dot(float2(-dir.y, dir.x), p - origin) * z2;
        float wobble = dist - pullback + sin(xdist * amzp_WOBBLE_FREQ) * amzp_WOBBLE_AMP;

        if (wobble > 0.0){
            float dotsize = rand21(float2(randz, 7.0)) * amzp_DOT_ADD + amzp_DOT_MIN;
            float patternsize = rand21(float2(randz, 8.0)) * amzp_PAT_ADD + amzp_PAT_MIN;
            float pattern = step(dotsize, length(fract(float2(dist, xdist) * patternsize) - 0.5)) * amzp_PAT_GAIN + amzp_PAT_BASE;

            float bright = 1.0;
            if (wobble < amzp_THRESH_1) bright = amzp_BRIGHT_1;
            else if (wobble < amzp_THRESH_2) bright = amzp_BRIGHT_2;
            else bright = pattern;

            float3 col = float3(r, g, b);
            float3 cacc = amzp_GAIN * col * shadow / (z2 + amzp_DENOM_BIAS) * bright;
            outc = cacc;
            outc = pow(max(outc, 0.0), float3(amzp_GAMMA));
            amzOutput = float4(outc, 1.0);
            return;
        } else {
            shadow *= 1.0 - exp((dist - pullback) * amzp_SHADOW_DECAY) * amzp_SHADOW_GAIN;
        }
    }

    amzOutput = float4(0.0, 0.0, 0.0, 1.0);
}

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

